from(bucket: "monitoring")
  |> range(start: -5m)
  |> filter(fn: (r) =>
    r._measurement == "zyxel_system" and
    r.source == "192.168.10.7"
  )
  |> filter(fn: (r) => r._field == "uptime")

  |> last()
  |> map(fn: (r) => ({
    r with _value: float(v: r._value) / 100.0
  }))
